-- Row counts for all tables
SELECT '=== ROW COUNTS ===' as verification;
SELECT 'countries' as table_name, COUNT(*) as row_count FROM countries
UNION ALL SELECT 'cities', COUNT(*) FROM cities
UNION ALL SELECT 'venues', COUNT(*) FROM venues
UNION ALL SELECT 'routing', COUNT(*) FROM routing
UNION ALL SELECT 'managers', COUNT(*) FROM managers
UNION ALL SELECT 'artists', COUNT(*) FROM artists
UNION ALL SELECT 'tours', COUNT(*) FROM tours
UNION ALL SELECT 'tour_legs', COUNT(*) FROM tour_legs
UNION ALL SELECT 'shows', COUNT(*) FROM shows
UNION ALL SELECT 'show_sequence', COUNT(*) FROM show_sequence
UNION ALL SELECT 'contract', COUNT(*) FROM contract
UNION ALL SELECT 'expense', COUNT(*) FROM expense
UNION ALL SELECT 'payment', COUNT(*) FROM payment
UNION ALL SELECT 'settlement', COUNT(*) FROM settlement
UNION ALL SELECT 'transport', COUNT(*) FROM transport
UNION ALL SELECT 'equipment', COUNT(*) FROM equipment
UNION ALL SELECT 'ticket_inventory', COUNT(*) FROM ticket_inventory
UNION ALL SELECT 'ticket_sale', COUNT(*) FROM ticket_sale
UNION ALL SELECT 'show_crew_assignment', COUNT(*) FROM show_crew_assignment
UNION ALL SELECT 'promoter', COUNT(*) FROM promoter
UNION ALL SELECT 'crew', COUNT(*) FROM crew
ORDER BY table_name;

-- Check for ANY duplicate crew assignments (should return 0 rows!)
SELECT '=== DUPLICATE CHECK (should be EMPTY) ===' as verification;
SELECT show_id, crew_id, COUNT(*) as duplicate_count
FROM show_crew_assignment
GROUP BY show_id, crew_id
HAVING COUNT(*) > 1;

-- Check ID ranges are correct
SELECT '=== ID RANGES ===' as verification;
SELECT 'shows' as entity, MIN(show_id) as min_id, MAX(show_id) as max_id, COUNT(*) as total FROM shows
UNION ALL SELECT 'crew', MIN(crew_id), MAX(crew_id), COUNT(*) FROM crew
UNION ALL SELECT 'venues', MIN(venue_id), MAX(venue_id), COUNT(*) FROM venues
UNION ALL SELECT 'show_crew assignments', MIN(assignment_id), MAX(assignment_id), COUNT(*) FROM show_crew_assignment;

-- Sample data preview
SELECT '=== SAMPLE DATA ===' as verification;
SELECT s.show_id, v.name as venue, COUNT(sca.crew_id) as crew_count
FROM shows s
LEFT JOIN venues v ON s.venue_id = v.venue_id
LEFT JOIN show_crew_assignment sca ON s.show_id = sca.show_id
GROUP BY s.show_id, v.name
ORDER BY s.show_id
LIMIT 10;

